mapper.select:
SELECT id AS factor_id, account_id, encrypted_secret, status, expires_at
  FROM mfa_factor
 WHERE account_id = #{accountId} AND id = #{factorId}
   AND factor_type = 'TOTP' AND status = 'PENDING' AND expires_at > #{now}

mapper.update:
UPDATE mfa_factor
   SET status = 'ACTIVE', verified_at = #{now}, expires_at = NULL,
       last_accepted_counter = #{acceptedCounter}, updated_at = #{now}
 WHERE id = #{factorId} AND account_id = #{accountId}
   AND factor_type = 'TOTP' AND status = 'PENDING' AND expires_at > #{now}

UPDATE account
   SET session_generation = GREATEST(session_generation, #{generation}), updated_at = #{now}
 WHERE id = #{accountId}
